<script setup lang="ts">
import { computed, ref } from 'vue';
import Icon from '../components/Icon.vue';
import { data, activeEmployees, headcountBudget, stageNames, exportCsv, navigate } from '../store';
const selectedDepartment=ref('');
const people=computed(()=>activeEmployees.value.filter(e=>!selectedDepartment.value||e.department===selectedDepartment.value));
const departments=computed(()=>data.departments.filter(d=>!selectedDepartment.value||d.name===selectedDepartment.value).map(d=>({...d,actual:activeEmployees.value.filter(e=>e.department===d.name).length})));
const budget=computed(()=>departments.value.reduce((n,d)=>n+d.headcountBudget,0));
const newPeople=computed(()=>people.value.filter(e=>e.joinDate.startsWith(data.meta.referenceDate.slice(0,7))).length);
const completion=computed(()=>{const p=data.performance.filter(p=>!selectedDepartment.value||p.department===selectedDepartment.value);return p.length?Math.round(p.filter(p=>p.status==='已完成').length/p.length*100):0;});
const experience=computed(()=>Array.from(new Set(people.value.map(e=>e.level))).sort().map(level=>({level,count:people.value.filter(e=>e.level===level).length})).filter(p=>p.count));
const locations=computed(()=>Array.from(new Set(people.value.map(e=>e.location))).map(name=>({name,count:people.value.filter(e=>e.location===name).length})).sort((a,b)=>b.count-a.count));
const denominator=computed(()=>Math.max(1,...departments.value.map(d=>Math.max(d.actual,d.headcountBudget))));
const filteredCandidates=computed(()=>data.candidates.filter(c=>!selectedDepartment.value||data.jobs.find(j=>j.id===c.jobId)?.department===selectedDepartment.value));
function download(){exportCsv('组织人力分析.csv',['部门','在职人数','编制预算','编制使用率','编制缺口','月度成本预算（元）'],departments.value.map(d=>[d.name,d.actual,d.headcountBudget,Math.round(d.actual/(d.headcountBudget||1)*100)+'%',Math.max(0,d.headcountBudget-d.actual),d.costBudget]));}
</script>
<template><div class="page-heading"><div><span class="eyebrow">PEOPLE ANALYTICS</span><h1>人力分析</h1><p class="page-subtitle">读懂人才数据，支持每一个组织决策。</p></div><div class="heading-actions"><select v-model="selectedDepartment" class="select-field" aria-label="分析部门"><option value="">全公司</option><option v-for="d in data.departments" :key="d.id">{{ d.name }}</option></select><button class="btn btn-primary" @click="download"><Icon name="download" :size="17"/>导出报表</button></div></div><div class="info-banner analytics-context"><Icon name="calendar" :size="18"/><p>统计基准：{{ data.meta.referenceDate }}<span>·</span>当前业务数据快照，筛选部门可查看对应指标</p></div><div class="metric-row"><div class="metric-card"><span class="metric-label">在职人数</span><div class="metric-value">{{ people.length }}<span>人</span></div><div class="metric-foot">正式员工与试用期员工</div></div><div class="metric-card"><span class="metric-label">编制使用率</span><div class="metric-value">{{ Math.round(people.length/(budget||1)*100) }}<span>%</span></div><div class="metric-foot">{{ people.length }} 实际 / {{ budget }} 预算</div></div><div class="metric-card"><span class="metric-label">本月入职且在职</span><div class="metric-value">{{ newPeople }}<span>人</span></div><div class="metric-foot">入职日期在 {{ data.meta.referenceDate.slice(0,7) }}</div></div><div class="metric-card"><span class="metric-label">绩效评审完成率</span><div class="metric-value">{{ completion }}<span>%</span></div><div class="metric-foot">已完成记录 / 全部绩效记录</div></div></div><div class="analytics-grid"><section class="panel"><div class="panel-header"><div><h2>部门编制分布</h2><p>业务扩张与人才储备，保持同一节奏</p></div><button class="text-button" @click="navigate('organization')">编制详情<Icon name="arrowUpRight" :size="16"/></button></div><div class="horizontal-bars"><div v-for="d in departments" :key="d.id" class="horizontal-bar-row"><span>{{ d.name }}</span><div class="horizontal-bar-track"><i class="horizontal-budget" :style="{width:d.headcountBudget/denominator*100+'%'}"></i><i class="horizontal-actual" :style="{width:d.actual/denominator*100+'%'}"></i></div><strong>{{ d.actual }}<small> / {{ d.headcountBudget }}</small></strong></div></div><div class="analytics-chart-foot"><span><i class="legend-dot blue-dot"></i>实际人数</span><span><i class="legend-dot pale-dot"></i>编制预算</span></div></section><section class="panel"><div class="panel-header"><div><h2>工作地点分布</h2><p>团队在哪里，协作就在哪里</p></div><Icon name="location"/></div><div class="location-analysis"><div class="donut" :style="{'--percent':Math.round((locations[0]?.count||0)/(people.length||1)*100)+'%'}"><div><strong>{{ locations.length }}</strong><span>个办公城市</span></div></div><div class="location-legend"><div v-for="(loc,i) in locations" :key="loc.name"><span><i class="legend-dot" :style="{background:i===0?'#526feb':'#dbe2f4'}"></i>{{ loc.name }}</span><strong>{{ loc.count }}<small>人</small></strong></div></div></div><p class="chart-explanation">蓝色代表人数最多的城市，其余城市合并为浅色区间。</p></section><section class="panel"><div class="panel-header"><div><h2>招聘阶段分布</h2><p>当前候选人快照 · 不代表历史转化率</p></div><Icon name="briefcase"/></div><div class="funnel-bars"><div v-for="(stage,i) in stageNames" :key="stage"><span>{{ stage }}</span><div :style="{background:['#eef1fc','#e5ebfd','#d8e2fb','#c7d6fb','#b8cef9'][i],width:Math.max(14,filteredCandidates.filter(c=>c.stage===stage).length/(Math.max(1,filteredCandidates.length))*180)+'%'}"><strong>{{ filteredCandidates.filter(c=>c.stage===stage).length }}</strong></div></div></div></section><section class="panel"><div class="panel-header"><div><h2>人才结构</h2><p>职级分布帮助评估团队梯队</p></div><Icon name="users"/></div><div class="level-chart"><div v-for="(level,i) in experience" :key="level.level"><strong>{{ level.count }}</strong><span :style="{height:Math.max(6,level.count/(people.length||1)*250)+'px',background:i===1?'#5471e8':'#dce4fa'}"></span><small>{{ level.level }}</small></div><div v-if="!experience.length" class="empty-state"><p>暂无职级数据</p></div></div><p class="chart-explanation">按当前筛选范围内在职员工的实际职级汇总。</p></section></div><div class="panel metric-dictionary"><div><Icon name="book" :size="22"/><h2>指标口径</h2><span>让每一个数字，都经得起追问。</span></div><p><strong>在职人数</strong>包含正式与试用，排除待入职和已离职；<strong>编制缺口</strong>为预算人数减在职人数，小于零时记为零；<strong>月度成本预算</strong>是计划值。本版没有真实薪资流水，不计算人均成本、离职率或招聘转化率。</p><span class="badge badge-muted">全公司编制预算 {{ headcountBudget }} 人</span></div></template>
